// Babylon.js相机控制示例
const canvas = document.getElementById('babylonCanvas');
const engine = new BABYLON.Engine(canvas, true);

const createScene = function() {
    const scene = new BABYLON.Scene(engine);
    scene.clearColor = new BABYLON.Color3(0.1, 0.1, 0.2);

    // 创建多个相机
    const camera1 = new BABYLON.ArcRotateCamera(
        'camera1',
        Math.PI / 2,
        Math.PI / 3,
        15,
        new BABYLON.Vector3(0, 0, 0),
        scene
    );
    camera1.attachControl(canvas, true);

    // 创建光源
    const light1 = new BABYLON.HemisphericLight(
        'light1',
        new BABYLON.Vector3(0, 1, 0),
        scene
    );
    light1.intensity = 0.7;

    const light2 = new BABYLON.DirectionalLight(
        'light2',
        new BABYLON.Vector3(-1, -2, -1),
        scene
    );
    light2.position = new BABYLON.Vector3(20, 40, 20);
    light2.intensity = 0.5;

    // 创建多个物体
    const box = BABYLON.MeshBuilder.CreateBox(
        'box',
        { size: 2 },
        scene
    );
    box.position.x = -3;
    box.position.y = 1;

    const sphere = BABYLON.MeshBuilder.CreateSphere(
        'sphere',
        { diameter: 2 },
        scene
    );
    sphere.position.x = 0;
    sphere.position.y = 1;

    const cylinder = BABYLON.MeshBuilder.CreateCylinder(
        'cylinder',
        { height: 2, diameter: 2 },
        scene
    );
    cylinder.position.x = 3;
    cylinder.position.y = 1;

    // 创建材质
    const boxMat = new BABYLON.StandardMaterial('boxMat', scene);
    boxMat.diffuseColor = new BABYLON.Color3(0.8, 0.2, 0.2);
    box.material = boxMat;

    const sphereMat = new BABYLON.StandardMaterial('sphereMat', scene);
    sphereMat.diffuseColor = new BABYLON.Color3(0.2, 0.8, 0.2);
    sphere.material = sphereMat;

    const cylinderMat = new BABYLON.StandardMaterial('cylinderMat', scene);
    cylinderMat.diffuseColor = new BABYLON.Color3(0.2, 0.2, 0.8);
    cylinder.material = cylinderMat;

    // 创建地面
    const ground = BABYLON.MeshBuilder.CreateGround(
        'ground',
        { width: 10, height: 10 },
        scene
    );

    const groundMat = new BABYLON.StandardMaterial('groundMat', scene);
    groundMat.diffuseColor = new BABYLON.Color3(0.3, 0.3, 0.3);
    ground.material = groundMat;

    // 添加相机控制按钮
    const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI('UI');

    const panel = new BABYLON.GUI.StackPanel();
    panel.width = '200px';
    panel.isVertical = true;
    panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    advancedTexture.addControl(panel);

    const header = new BABYLON.GUI.TextBlock();
    header.text = '相机控制';
    header.height = '30px';
    header.color = 'white';
    panel.addControl(header);

    // 创建相机位置按钮
    const positions = [
        { name: '正面', alpha: Math.PI / 2, beta: Math.PI / 3 },
        { name: '侧面', alpha: 0, beta: Math.PI / 3 },
        { name: '顶部', alpha: Math.PI / 2, beta: 0 },
        { name: '背面', alpha: -Math.PI / 2, beta: Math.PI / 3 }
    ];

    positions.forEach(pos => {
        const button = BABYLON.GUI.Button.CreateSimpleButton(
            pos.name,
            pos.name
        );
        button.width = '100px';
        button.height = '30px';
        button.color = 'white';
        button.background = 'green';
        button.onPointerUpObservable.add(() => {
            camera1.alpha = pos.alpha;
            camera1.beta = pos.beta;
        });
        panel.addControl(button);
    });

    // 添加动画
    scene.registerBeforeRender(function() {
        box.rotation.y += 0.01;
        sphere.rotation.y += 0.02;
        cylinder.rotation.y += 0.015;
    });

    return scene;
};

const scene = createScene();

engine.runRenderLoop(function() {
    scene.render();
});

window.addEventListener('resize', function() {
    engine.resize();
});

