// Babylon.js材质与光照示例
const canvas = document.getElementById('babylonCanvas');
const engine = new BABYLON.Engine(canvas, true);

const createScene = function() {
    const scene = new BABYLON.Scene(engine);
    scene.clearColor = new BABYLON.Color3(0.05, 0.05, 0.1);

    // 创建相机
    const camera = new BABYLON.ArcRotateCamera(
        'camera',
        Math.PI / 2,
        Math.PI / 3,
        15,
        new BABYLON.Vector3(0, 0, 0),
        scene
    );
    camera.attachControl(canvas, true);

    // 创建环境光
    const ambientLight = new BABYLON.HemisphericLight(
        'ambientLight',
        new BABYLON.Vector3(0, 1, 0),
        scene
    );
    ambientLight.intensity = 0.3;
    ambientLight.diffuse = new BABYLON.Color3(0.5, 0.5, 0.7);

    // 创建方向光
    const directionalLight = new BABYLON.DirectionalLight(
        'directionalLight',
        new BABYLON.Vector3(-1, -2, -1),
        scene
    );
    directionalLight.position = new BABYLON.Vector3(20, 40, 20);
    directionalLight.intensity = 0.7;

    // 创建点光源
    const pointLight = new BABYLON.PointLight(
        'pointLight',
        new BABYLON.Vector3(0, 5, 0),
        scene
    );
    pointLight.diffuse = new BABYLON.Color3(1, 0.5, 0);
    pointLight.intensity = 0.5;

    // 创建材质示例
    const materials = [];

    // 标准材质
    const standardMat = new BABYLON.StandardMaterial('standardMat', scene);
    standardMat.diffuseColor = new BABYLON.Color3(0.7, 0.2, 0.2);
    standardMat.specularColor = new BABYLON.Color3(0.5, 0.5, 0.5);
    standardMat.specularPower = 32;
    materials.push(standardMat);

    // 金属材质
    const metalMat = new BABYLON.StandardMaterial('metalMat', scene);
    metalMat.diffuseColor = new BABYLON.Color3(0.8, 0.8, 0.8);
    metalMat.specularColor = new BABYLON.Color3(1, 1, 1);
    metalMat.specularPower = 64;
    metalMat.metallic = 1.0;
    materials.push(metalMat);

    // 玻璃材质
    const glassMat = new BABYLON.StandardMaterial('glassMat', scene);
    glassMat.diffuseColor = new BABYLON.Color3(0.2, 0.2, 0.8);
    glassMat.alpha = 0.3;
    glassMat.specularColor = new BABYLON.Color3(1, 1, 1);
    glassMat.specularPower = 128;
    materials.push(glassMat);

    // 创建物体展示材质
    const sphere1 = BABYLON.MeshBuilder.CreateSphere(
        'sphere1',
        { diameter: 2 },
        scene
    );
    sphere1.position.x = -3;
    sphere1.position.y = 1;
    sphere1.material = standardMat;

    const sphere2 = BABYLON.MeshBuilder.CreateSphere(
        'sphere2',
        { diameter: 2 },
        scene
    );
    sphere2.position.x = 0;
    sphere2.position.y = 1;
    sphere2.material = metalMat;

    const sphere3 = BABYLON.MeshBuilder.CreateSphere(
        'sphere3',
        { diameter: 2 },
        scene
    );
    sphere3.position.x = 3;
    sphere3.position.y = 1;
    sphere3.material = glassMat;

    // 创建地面
    const ground = BABYLON.MeshBuilder.CreateGround(
        'ground',
        { width: 10, height: 10 },
        scene
    );

    const groundMat = new BABYLON.StandardMaterial('groundMat', scene);
    groundMat.diffuseColor = new BABYLON.Color3(0.2, 0.2, 0.2);
    ground.material = groundMat;

    // 添加点光源动画
    let alpha = 0;
    scene.registerBeforeRender(function() {
        pointLight.position.x = Math.cos(alpha) * 5;
        pointLight.position.z = Math.sin(alpha) * 5;
        alpha += 0.01;
    });

    return scene;
};

const scene = createScene();

engine.runRenderLoop(function() {
    scene.render();
});

window.addEventListener('resize', function() {
    engine.resize();
});
